/**
 * Fails the pack/publish if the generated payload of this package is missing.
 *
 * `@hashintel/ds-helpers` publishes nothing but `styled-system/**`, which is
 * git-ignored, generated by `@hashintel/ds-components`' Panda codegen and copied
 * here by `sync-styled-system.mjs`. If that directory is absent or incomplete
 * when npm builds the tarball, npm still produces a *valid* tarball — it just
 * contains the six metadata files and no code, and every `exports` entry point
 * dangles. That has shipped to the registry three times (0.1.1, 0.2.0, 0.2.1).
 *
 * This script turns that silent failure into a failed publish. It resolves
 * every literal target reachable from `main`/`module`/`types`/`exports` and
 * asserts each one exists on disk and is non-empty, and that every directory
 * listed in `files` contains at least one file.
 *
 * Intentionally dependency-free: this package declares no dependencies and must
 * keep it that way, and the script must run under a bare `node` during
 * `prepack`.
 */

import { readFileSync, readdirSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const packageDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const manifest = JSON.parse(
  readFileSync(join(packageDir, "package.json"), "utf8"),
);

/** @type {Map<string, string>} target relative path -> manifest field it came from */
const targets = new Map();

/**
 * @param {string} field
 * @param {unknown} value
 */
const collect = (field, value) => {
  if (typeof value === "string") {
    if (value.startsWith("./") && !value.includes("*")) {
      targets.set(value.slice(2), field);
    }
    return;
  }

  if (value && typeof value === "object") {
    for (const [key, nested] of Object.entries(value)) {
      collect(`${field}.${key}`, nested);
    }
  }
};

for (const field of ["main", "module", "types", "typings", "browser"]) {
  if (manifest[field]) {
    collect(field, manifest[field]);
  }
}
collect("exports", manifest.exports);

/** @type {string[]} */
const problems = [];

for (const [target, field] of targets) {
  const absolute = join(packageDir, target);
  let stats;
  try {
    stats = statSync(absolute);
  } catch {
    problems.push(`missing: ${target} (referenced by "${field}")`);
    continue;
  }
  if (!stats.isFile() || stats.size === 0) {
    problems.push(`empty: ${target} (referenced by "${field}")`);
  }
}

const countFiles = (/** @type {string} */ directory) => {
  let total = 0;
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    total += entry.isDirectory() ? countFiles(join(directory, entry.name)) : 1;
  }
  return total;
};

for (const entry of manifest.files ?? []) {
  const absolute = join(packageDir, entry);
  let stats;
  try {
    stats = statSync(absolute);
  } catch {
    // `files` legitimately lists names that may not exist (for example
    // `LICENSE`); only directories that do exist are checked for emptiness.
    continue;
  }
  if (stats.isDirectory() && countFiles(absolute) === 0) {
    problems.push(`empty directory: ${entry} (listed in "files")`);
  }
}

/**
 * Whole-tree check.
 *
 * The entry-point checks above are necessary but nowhere near sufficient: a
 * `styled-system/` truncated to just its `index` files satisfies every one of
 * them, and would pack a tarball that imports cleanly and then fails at the
 * first token lookup. That is not hypothetical — it is what an earlier revision
 * of `sync-styled-system.mjs` could install from a mid-generation source, and
 * this verifier passed it.
 *
 * The payload is therefore compared against `expected-payload.json`, a
 * checked-in list of every file Panda produces here. It deliberately is *not*
 * derived from what the sync just did: a record written by the same step that
 * may have truncated the tree cannot detect the truncation.
 */
const expected = JSON.parse(
  readFileSync(join(packageDir, "expected-payload.json"), "utf8"),
);

const payloadRoot = join(packageDir, expected.directory);

/**
 * @param {string} directory
 * @param {string} [prefix]
 * @returns {string[]}
 */
const listFiles = (directory, prefix = "") => {
  /** @type {string[]} */
  const found = [];
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const relativePath = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) {
      found.push(...listFiles(join(directory, entry.name), relativePath));
    } else {
      found.push(relativePath);
    }
  }
  return found;
};

/** @type {string[]} */
let present = [];
try {
  present = listFiles(payloadRoot);
} catch {
  problems.push(`${expected.directory}/ is missing entirely`);
}

const presentSet = new Set(present);

const absent = expected.files.filter(
  (/** @type {string} */ path) => !presentSet.has(path),
);
if (absent.length > 0) {
  problems.push(
    `${absent.length} of ${expected.files.length} expected generated file(s) ` +
      `are missing from ${expected.directory}/, including ` +
      `${absent.slice(0, 5).join(", ")}`,
  );
}

const emptyFiles = expected.files.filter((/** @type {string} */ path) => {
  if (!presentSet.has(path)) {
    return false;
  }
  try {
    return statSync(join(payloadRoot, path)).size === 0;
  } catch {
    return true;
  }
});
if (emptyFiles.length > 0) {
  problems.push(
    `${emptyFiles.length} generated file(s) are empty, including ` +
      `${emptyFiles.slice(0, 5).join(", ")}`,
  );
}

const unexpected = present.filter((path) => !expected.files.includes(path));
if (unexpected.length > 0) {
  problems.push(
    `${unexpected.length} unexpected file(s) in ${expected.directory}/, ` +
      `including ${unexpected.slice(0, 5).join(", ")} — either stale output or ` +
      `\`expected-payload.json\` needs regenerating`,
  );
}

if (problems.length > 0) {
  console.error(
    `\n${manifest.name}: refusing to pack — the generated payload is incomplete.\n`,
  );
  for (const problem of problems) {
    console.error(`  - ${problem}`);
  }
  console.error(
    "\nRun `yarn workspace @hashintel/ds-components codegen` to regenerate " +
      "`styled-system/`, then try again.\n",
  );
  process.exit(1);
}

console.log(
  `${manifest.name}: verified ${targets.size} entry-point target(s) and all ` +
    `${expected.files.length} generated file(s).`,
);
